        return 2;
    }
}

contract WithArgs {
    uint public value;

    function WithArgs(uint x) public {
        value = x;
    }
}

contract UsesArgs is WithArgs(42) {
    function UsesArgs() public {
    }

    function () public payable {
        revert();
    }
}
